const std = @import("std");

pub fn main() !void {
    var a: i32 = 10;
    var b: i32 = 20;

    std.debug.print("Before: {} {}\n", .{a, b});

    // Swap a and b
    const temp = a;
    a = b;
    b = temp;

    std.debug.print("After: {} {}\n", .{a, b});
}

